import Db from"./../db/db.js";import Expense from"./../expenses/expenses/expenses.js";export default class ManagerExpenses{constructor(){this.db=new Db,this.expenses=this.db.retrieveAllRecords().map((e=>new Expense(e.data,e.tipo,e.descricao,e.valor)))}addExpenses(e){if(!e.validateData())throw new Error("Dados inválidos");this.db.grave(e),this.expenses.push(e)}getAllExpenses(){return this.expenses}searchExpenses(e){return this.expenses.filter((s=>Object.keys(e).every((t=>""===e[t]||("data"===t||"type"===t||"description"===t||"value"===t)&&(s.data,s.tipo,s.descricao,s.valor===e[t])))))}removeExpense(e){this.db.remove(e),this.expenses=this.expenses.filter((s=>s.id!=e))}}